// ---------------------------------------------------------------------------
// Pixel Whiskey — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_d42m = [
  A('px/h_0.png'),
  A('px/h_1.png'),
  A('px/h_2.png'),
  A('px/h_3.png'),
  A('px/h_4.png'),
  A('px/h_5.png'),
  A('px/h_6.png'),
  A('px/h_7.png'),
  A('px/h_8.png'),
  A('px/h_9.png'),
]

const img_Weekday_q4oq = [
  A('week_w1.png'),
  A('week_w2.png'),
  A('week_w3.png'),
  A('week_w4.png'),
  A('week_w5.png'),
  A('week_w6.png'),
  A('week_w7.png'),
]

const img_Day_v4vu = [
  A('px/d_0.png'),
  A('px/d_1.png'),
  A('px/d_2.png'),
  A('px/d_3.png'),
  A('px/d_4.png'),
  A('px/d_5.png'),
  A('px/d_6.png'),
  A('px/d_7.png'),
  A('px/d_8.png'),
  A('px/d_9.png'),
]

const img_Temperature_h3rh = [
  A('px/t_0.png'),
  A('px/t_1.png'),
  A('px/t_2.png'),
  A('px/t_3.png'),
  A('px/t_4.png'),
  A('px/t_5.png'),
  A('px/t_6.png'),
  A('px/t_7.png'),
  A('px/t_8.png'),
  A('px/t_9.png'),
]

const img_Hour_Aod_z5f1 = [
  A('px/a_0.png'),
  A('px/a_1.png'),
  A('px/a_2.png'),
  A('px/a_3.png'),
  A('px/a_4.png'),
  A('px/a_5.png'),
  A('px/a_6.png'),
  A('px/a_7.png'),
  A('px/a_8.png'),
  A('px/a_9.png'),
]

WatchFace({
  initView() {
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Ice and glint (IMG)
    W.gl = ui.createWidget(ui.widget.IMG, {
      x: px(39),
      y: px(279),
      src: A('fz/gl_0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(231),
      minute_startY: px(87),
      minute_zero: 1,
      minute_space: px(12),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_d42m,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(39),
      hour_startY: px(87),
      hour_zero: 1,
      hour_space: px(12),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_d42m,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(191),
      y: px(192),
      week_en: img_Weekday_q4oq,
      week_sc: img_Weekday_q4oq,
      week_tc: img_Weekday_q4oq,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(195),
      day_startY: px(279),
      day_zero: 0,
      day_space: px(12),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_v4vu,
      day_sc_array: img_Day_v4vu,
      day_tc_array: img_Day_v4vu,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(156),
      y: px(351),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Temperature_h3rh,
      h_space: px(12),
      align_h: ui.align.RIGHT,
      unit_en: A('px/unit.png'),
      unit_sc: A('px/unit.png'),
      unit_tc: A('px/unit.png'),
      negative_image: A('px/minus.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(39),
      minute_startY: px(87),
      minute_zero: 1,
      minute_space: px(12),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_Aod_z5f1,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(231),
      hour_startY: px(87),
      hour_zero: 1,
      hour_space: px(12),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Aod_z5f1,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    W.col = ui.createWidget(ui.widget.IMG, {
      x: px(183),
      y: px(87),
      src: A('px/colon.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Colon Aod (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(183),
      y: px(87),
      src: A('px/a_colon.png'),
      show_level: ui.show_level.ONLY_AOD
    })


    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // 8 frames of 160 ms as in the reference: the ice cubes bob and a glint slides across the whiskey; the colon blinks (on for the first 4 frames).
      const C = 12, OX = 3, OY = 3, SH = 5, MS = 80
      const X = (c) => OX + c * C, Y = (r) => OY + (r + SH) * C
      const last = {}
      const put = (k, x, y, src) => {
        const key = x + '|' + y + '|' + src
        if (last[k] === key) return
        last[k] = key
        W[k].setProperty(ui.prop.MORE, { x: pxv(x), y: pxv(y), src: A(src) })
      }
      const tick = () => {
        const f = Math.floor(Date.now() / 160) % 8
        put('gl', X(3), Y(18), 'fz/gl_' + f + '.png')
        put('col', X(15), Y(2), f < 4 ? 'px/colon.png' : 'fz/blank.png')
      }
      let id = null
      const safe = () => { try { tick() } catch (e) {} }
      const start = () => { if (id === null) { try { id = setInterval(safe, MS) } catch (e) {} } }
      const stop = () => { if (id !== null) { try { clearInterval(id) } catch (e) {} id = null } }
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop })
      safe()
      start()
    }

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
